// ===== EMBEDDED CREST (one very long line, do not edit; your code starts below) =====
const HEMIPT_LOGO = "data:image/png;base64,";
// ===== END EMBEDDED CREST =====

(() => {
  "use strict";

  // ====== EDIT THESE ======
  // The crest is embedded at the very top of this file (HEMIPT_LOGO).
  const LOGO_SRCS = [HEMIPT_LOGO, "assets/HEMIPT%20UNIVERSITY%20Logo%202.jpg"].filter(Boolean);
  const FACULTIES = [
    "Engineering & Technology",
    "Health Sciences",
    "Business & Management",
    "Education",
    "Arts & Humanities"
  ];
  const CATS = {
    matric: {
      pillText: "MATRICULATING STUDENT", pill: "#0f3d6e", student: true,
      classLine: "CLASS OF 2026 - NEW STUDENT",
      tagline: "Welcome to a Journey of Learning & Growth"
    },
    grad: {
      pillText: "GRADUATING STUDENT", pill: "#7a1226", student: true,
      classLine: "CLASS OF 2026 - GRADUATING CLASS",
      tagline: "Honouring Accomplishment & Leadership"
    },
    guest: {
      pillText: "INVITED GUEST", pill: "#0f4d2a", guest: true,
      defaultTitle: "HONOURED GUEST",
      classLine: "CLASS OF 2026 CELEBRATION",
      tagline: "Celebrating New Beginnings & Academic Excellence"
    },
    lecturer: {
      pillText: "LECTURER", pill: "#1a3a5c", staff: true,
      field1Label: "Faculty", field1Placeholder: "e.g. Engineering & Technology",
      field2Label: "Designation", field2Placeholder: "e.g. Senior Lecturer",
      classLine: "CLASS OF 2026 JOINT CEREMONY",
      tagline: "Shaping Minds & Building Futures"
    },
    admin: {
      pillText: "ADMINISTRATOR", pill: "#4a2060", staff: true,
      field1Label: "Department", field1Placeholder: "e.g. Registry & Student Affairs",
      field2Label: "Position", field2Placeholder: "e.g. Head of Registry",
      classLine: "CLASS OF 2026 JOINT CEREMONY",
      tagline: "Empowering Excellence in Education"
    },
    facilitator: {
      pillText: "FACILITATOR", pill: "#6b3a1f", staff: true,
      field1Label: "Department", field1Placeholder: "e.g. Student Support Services",
      field2Label: "Role", field2Placeholder: "e.g. Academic Facilitator",
      classLine: "CLASS OF 2026 JOINT CEREMONY",
      tagline: "Guiding the Journey of Learning"
    }
  };
  const MOTTO = "ORARE ET LABORARE";
  // ========================

  const GREEN = "#0f4d2a", GOLD = "#b8923f", INK = "#0f1f3d", CREAM = "#f8f6ee";
  const SERIF = "Georgia, 'Times New Roman', serif";
  const PHOTO_BOX = { x: 288, y: 436, w: 324, h: 380, r: 36 };
  const WATERMARK_ALPHA = 0.16;        // raise for a stronger watermark (0.1 - 0.25)
  const WATERMARK_HEIGHT = 600;         // size of the big faint crest
  const WATERMARK_CY = 640;             // vertical centre of the watermark
  const PHOTO_MAX_SCALE = 2;            // stored selfie is at most 2x the frame size

  const $ = id => document.getElementById(id);
  const canvas = $("badge");
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height;

  // Static layer (frame, crest, title, placeholder) is drawn once and reused.
  const base = document.createElement("canvas");
  base.width = W; base.height = H;
  const bctx = base.getContext("2d");

  const catEl = $("cat"), nameEl = $("name"), facEl = $("faculty"),
        progEl = $("program"), titleEl = $("guestTitle"), photoEl = $("photo"),
        photoLiveEl = $("photoLive"), clearEl = $("clearPhoto"), msg = $("msg"),
      staffDeptEl = $("staffDept"), staffRoleEl = $("staffRole");

  let logo = null, photo = null;
  let rafId = 0, blobPromise = null, blobTimer = 0, photoToken = 0;

  // ---------- helpers (all take the target context) ----------
  function roundRect(c, x, y, w, h, r) {
    c.beginPath();
    c.moveTo(x + r, y);
    c.arcTo(x + w, y, x + w, y + h, r);
    c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r);
    c.arcTo(x, y, x + w, y, r);
    c.closePath();
  }

  // Text width scales linearly with font size, so one measurement is enough.
  function fit(c, text, maxW, start, min, weight, style) {
    const font = s => `${style} ${weight} ${s}px ${SERIF}`;
    c.font = font(start);
    const w = c.measureText(text).width;
    const size = w > maxW ? Math.max(min, Math.floor(start * maxW / w)) : start;
    c.font = font(size);
  }

  function line(c, text, y, color, maxW, start, min, weight, style = "normal") {
    c.fillStyle = color;
    c.textAlign = "center";
    fit(c, text, maxW, start, min, weight, style);
    c.fillText(text, W / 2, y);
  }

  // one line made of differently coloured pieces
  function segments(c, parts, y, maxW, start, min) {
    fit(c, parts.map(p => p.t).join(""), maxW, start, min, "bold", "normal");
    const total = parts.reduce((n, p) => n + c.measureText(p.t).width, 0);
    let x = W / 2 - total / 2;
    c.textAlign = "left";
    for (const p of parts) {
      c.fillStyle = p.c;
      c.fillText(p.t, x, y);
      x += c.measureText(p.t).width;
    }
    c.textAlign = "center";
  }

  function drawPlaceholder(c, fx, fy, fw, fh) {
    c.fillStyle = "#e9e7df";
    c.fillRect(fx, fy, fw, fh);
    c.fillStyle = "#b9b6ab";
    c.beginPath(); c.ellipse(fx + fw / 2, fy + 135, 70, 88, 0, 0, Math.PI * 2); c.fill();
    c.beginPath(); c.ellipse(fx + fw / 2, fy + fh + 10, 150, 150, 0, 0, Math.PI * 2); c.fill();
    const cx = fx + fw / 2, cy = fy + fh - 60;     // camera icon
    c.fillStyle = "#8f8c82";
    roundRect(c, cx - 36, cy - 24, 72, 50, 8); c.fill();
    c.fillRect(cx - 14, cy - 32, 28, 10);
    c.fillStyle = "#e9e7df";
    c.beginPath(); c.arc(cx, cy + 1, 15, 0, Math.PI * 2); c.fill();
    c.fillStyle = "#8f8c82";
    c.beginPath(); c.arc(cx, cy + 1, 9, 0, Math.PI * 2); c.fill();
  }

  // ---------- static layer ----------
  function drawBase() {
    const c = bctx;
    c.clearRect(0, 0, W, H);

    c.fillStyle = GREEN; c.fillRect(0, 0, W, H);
    c.strokeStyle = GOLD; c.lineWidth = 4;
    c.strokeRect(16, 16, W - 32, H - 32);
    c.fillStyle = CREAM; c.fillRect(38, 38, W - 76, H - 76);
    c.lineWidth = 3; c.strokeRect(46, 46, W - 92, H - 92);

    if (logo) {                                   // large faint crest watermark behind the photo
      c.save(); c.globalAlpha = WATERMARK_ALPHA;
      c.imageSmoothingQuality = "high";
      const s = WATERMARK_HEIGHT / logo.height;
      c.drawImage(logo, W / 2 - logo.width * s / 2, WATERMARK_CY - WATERMARK_HEIGHT / 2, logo.width * s, WATERMARK_HEIGHT);
      c.restore();
    }

    c.fillStyle = "#cfd2cc"; roundRect(c, W / 2 - 78, 62, 156, 28, 14); c.fill();   // lanyard slot
    c.fillStyle = "#e4e0d2"; c.beginPath(); c.arc(W / 2, 58, 15, 0, Math.PI * 2); c.fill();
    c.strokeStyle = GOLD; c.lineWidth = 3; c.stroke();

    if (logo) {                                   // crest
      const s = Math.min(150 / logo.width, 150 / logo.height);
      c.drawImage(logo, W / 2 - logo.width * s / 2, 175 - logo.height * s / 2, logo.width * s, logo.height * s);
    } else {
      c.fillStyle = GREEN; c.beginPath(); c.arc(W / 2, 175, 62, 0, Math.PI * 2); c.fill();
      c.fillStyle = "#fff"; c.textAlign = "center"; c.textBaseline = "middle";
      c.font = "bold 70px " + SERIF; c.fillText("H", W / 2, 179);
      c.textBaseline = "alphabetic";
    }

    line(c, "HEMIPT UNIVERSITY INSTITUTE", 296, GREEN, 800, 46, 26, "bold");
    segments(c, [{ t: "JOINT MATRICULATION ", c: GREEN }, { t: "&", c: GOLD }], 346, 800, 46, 26);
    segments(c, [{ t: "GRADUATION ", c: GOLD }, { t: "CEREMONY", c: GREEN }], 394, 800, 46, 26);

    c.strokeStyle = GOLD; c.lineWidth = 2;        // divider
    c.beginPath();
    c.moveTo(190, 416); c.lineTo(430, 416);
    c.moveTo(470, 416); c.lineTo(710, 416);
    c.stroke();
    c.fillStyle = GOLD;
    c.beginPath(); c.moveTo(450, 408); c.lineTo(458, 416); c.lineTo(450, 424); c.lineTo(442, 416); c.fill();

    const { x, y, w, h, r } = PHOTO_BOX;          // photo placeholder
    c.save();
    roundRect(c, x, y, w, h, r); c.clip();
    drawPlaceholder(c, x, y, w, h);
    c.restore();

    c.textAlign = "center";
    line(c, MOTTO, 1152, GREEN, 500, 18, 12, "normal");
  }

  // ---------- dynamic layer ----------
  function draw() {
    rafId = 0;
    const cat = CATS[catEl.value];
    const name = (nameEl.value.trim() || "YOUR NAME").toUpperCase();

    ctx.drawImage(base, 0, 0);

    const { x, y, w, h, r } = PHOTO_BOX;
    if (photo) {
      ctx.save();
      roundRect(ctx, x, y, w, h, r); ctx.clip();
      const s = Math.max(w / photo.width, h / photo.height);
      const dw = photo.width * s, dh = photo.height * s;
      ctx.drawImage(photo, x + (w - dw) / 2, y + (h - dh) * 0.3, dw, dh);
      ctx.restore();
    }
    ctx.strokeStyle = GOLD; ctx.lineWidth = 8;
    roundRect(ctx, x, y, w, h, r); ctx.stroke();

    line(ctx, name, 905, INK, 780, 72, 34, "bold");

    const py = 930, ph = 66;                       // category pill
    ctx.font = "bold 38px " + SERIF;
    const pw = Math.min(780, ctx.measureText(cat.pillText).width + 100);
    ctx.fillStyle = GOLD; roundRect(ctx, W / 2 - pw / 2, py, pw, ph, 33); ctx.fill();
    ctx.fillStyle = cat.pill; roundRect(ctx, W / 2 - pw / 2 + 6, py + 6, pw - 12, ph - 12, 27); ctx.fill();
    line(ctx, cat.pillText, py + 46, "#e7c872", pw - 60, 38, 22, "bold");

    if (cat.student) {
      line(ctx, ("FACULTY OF " + facEl.value).toUpperCase(), 1034, INK, 780, 32, 18, "bold");
      const prog = progEl.value.trim();
      if (prog) line(ctx, prog, 1066, GREEN, 780, 26, 16, "normal", "italic");
      line(ctx, cat.classLine, 1102, INK, 780, 36, 20, "bold");
      line(ctx, cat.tagline, 1130, GOLD, 780, 24, 16, "bold");
    } else if (cat.staff) {
      const dept = staffDeptEl.value.trim();
      const role = staffRoleEl.value.trim();
      if (dept) line(ctx, dept.toUpperCase(), 1034, INK, 780, 32, 18, "bold");
      if (role) line(ctx, role, 1066, GREEN, 780, 26, 16, "normal", "italic");
      line(ctx, cat.classLine, 1102, INK, 780, 36, 20, "bold");
      line(ctx, cat.tagline, 1130, GOLD, 780, 24, 16, "bold");
    } else {
      const title = (titleEl.value.trim() || cat.defaultTitle).toUpperCase();
      line(ctx, title, 1042, INK, 780, 32, 18, "bold");
      line(ctx, cat.classLine, 1078, INK, 780, 28, 16, "normal");
      line(ctx, cat.tagline, 1110, INK, 780, 26, 16, "normal");
    }

    // The image changed: drop the cached PNG and re-encode it once typing stops,
    // so Save/Share respond instantly (important for the share-sheet user gesture on iOS).
    blobPromise = null;
    clearTimeout(blobTimer);
    blobTimer = setTimeout(getBlob, 600);
  }

  // Coalesce rapid input events into one draw per frame.
  function schedule() { if (!rafId) rafId = requestAnimationFrame(draw); }

  function getBlob() {
    return blobPromise || (blobPromise = new Promise(res => {
      try { canvas.toBlob(res, "image/png"); } catch { res(null); }   // e.g. tainted canvas on file://
    }));
  }

  // ---------- images ----------
  function loadImage(src) {
    return new Promise(res => {
      const img = new Image();
      img.onload = () => res(img);
      img.onerror = () => res(null);
      img.src = src;
    });
  }

  // Decode, fix EXIF rotation, and downscale big phone photos to a small canvas.
  async function prepPhoto(file) {
    let src, close = () => {};
    try {
      src = await createImageBitmap(file, { imageOrientation: "from-image" });
      close = () => src.close();
    } catch {
      const url = URL.createObjectURL(file);
      src = await loadImage(url);
      URL.revokeObjectURL(url);
      if (!src) return null;
    }
    const sw = src.width, sh = src.height;
    const k = Math.min(1, Math.max(
      PHOTO_BOX.w * PHOTO_MAX_SCALE / sw,
      PHOTO_BOX.h * PHOTO_MAX_SCALE / sh
    ));
    const out = document.createElement("canvas");
    out.width = Math.max(1, Math.round(sw * k));
    out.height = Math.max(1, Math.round(sh * k));
    const octx = out.getContext("2d");
    octx.imageSmoothingQuality = "high";
    octx.drawImage(src, 0, 0, out.width, out.height);
    close();
    return out;
  }

  // ---------- UI ----------
  const frag = document.createDocumentFragment();
  FACULTIES.forEach(f => {
    const o = document.createElement("option");
    o.value = o.textContent = f;
    frag.appendChild(o);
  });
  facEl.appendChild(frag);

  function refreshFields() {
    const cat = CATS[catEl.value];
    $("studentFields").classList.toggle("hidden", !cat.student);
    $("guestFields").classList.toggle("hidden", !cat.guest);
    $("staffFields").classList.toggle("hidden", !cat.staff);
    if (cat.staff) {
      $("staffField1Label").textContent = cat.field1Label;
      staffDeptEl.placeholder = cat.field1Placeholder;
      $("staffField2Label").textContent = cat.field2Label;
      staffRoleEl.placeholder = cat.field2Placeholder;
    }
    schedule();
  }

  async function handlePhotoFile(f) {
    if (!f) return;
    msg.textContent = "Loading photo…";
    const token = ++photoToken;
    const img = await prepPhoto(f).catch(() => null);
    if (token !== photoToken) return;               // a newer choice or removal won
    if (!img) { msg.textContent = "That file could not be read. Try another photo."; return; }
    photo = img;
    clearEl.classList.remove("hidden");
    msg.textContent = "";
    schedule();
  }
  photoEl.addEventListener("change", e => handlePhotoFile(e.target.files[0]));
  photoLiveEl.addEventListener("change", e => handlePhotoFile(e.target.files[0]));
  $("takePhoto").addEventListener("click", () => { photoLiveEl.value = ""; photoLiveEl.click(); });
  $("pickPhoto").addEventListener("click", () => { photoEl.value = ""; photoEl.click(); });
  clearEl.addEventListener("click", () => {
    photoToken++; photo = null; photoEl.value = ""; photoLiveEl.value = "";
    clearEl.classList.add("hidden");
    schedule();
  });

  [nameEl, progEl, titleEl, staffDeptEl, staffRoleEl].forEach(i => i.addEventListener("input", schedule));
  facEl.addEventListener("change", schedule);
  catEl.addEventListener("change", refreshFields);

  $("save").addEventListener("click", async () => {
    const btn = $("save");
    btn.disabled = true; btn.textContent = "Saving…";
    try {
      const blob = await getBlob();
      if (!blob) { msg.textContent = "Could not create the image. Please try again."; return; }
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      const safe = (nameEl.value.trim() || "badge").replace(/[^a-z0-9]+/gi, "-").toLowerCase();
      a.href = url; a.download = "hemipt-badge-" + safe + ".png";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
      msg.textContent = "Saved. Check your Downloads or Photos.";
    } finally {
      btn.disabled = false; btn.textContent = "Save badge";
    }
  });

  $("share").addEventListener("click", async () => {
    const btn = $("share");
    btn.disabled = true; btn.textContent = "Sharing…";
    try {
      const text = "I’m at the HEMIPT Joint Matriculation & Graduation Ceremony, Class of 2026!";
      const blob = await getBlob();
      if (blob) {
        const file = new File([blob], "hemipt-badge.png", { type: "image/png" });
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try { await navigator.share({ files: [file], text }); return; }
          catch (e) { if (e.name === "AbortError") return; }
        }
      }
      // Fallback: show share panel with individual platform links
      const pageUrl = location.href;
      $("shareWa").href = "https://wa.me/?text=" + encodeURIComponent(text + " Make yours: " + pageUrl);
      $("shareFb").href = "https://www.facebook.com/sharer/sharer.php?u=" + encodeURIComponent(pageUrl);
      $("shareX").href  = "https://twitter.com/intent/tweet?text=" + encodeURIComponent(text) + "&url=" + encodeURIComponent(pageUrl);
      $("sharePanel").classList.remove("hidden");
    } finally {
      btn.disabled = false; btn.textContent = "Share";
    }
  });

  // ---------- init ----------
  drawBase();
  refreshFields();
  (async () => {
    for (const src of LOGO_SRCS) {
      const img = await loadImage(src);
      if (img) { logo = img; drawBase(); schedule(); return; }
    }
    msg.textContent = "Logo failed to load. Make sure script.js was copied completely.";
  })();
})();
